/bin/bash -lc "python - <<'PY'
from bioblend.galaxy.histories import HistoryClient
import inspect
for name in dir(HistoryClient):
    if 'histor' in name.lower() or 'copy' in name.lower():
        obj=getattr(HistoryClient,name)
        if callable(obj):
            try: print(name, inspect.signature(obj))
            except Exception: print(name)
PY"

